    {
      "service": "user",
      "fault_kind": "pod_unavailable",
      "evidence": [
        {"kind": "metric", "sql": "SELECT service_name, metric, count(*) n, round(avg(value),2) avg_v FROM abnormal_metrics WHERE metric='k8s.deployment.available' AND service_name='user' GROUP BY 1,2", "claim": "User deployment available is 0 across the whole abnormal window, versus 1.0 in the normal period."},
        {"kind": "trace", "sql": "SELECT span_name, attr_status_code, count(*) n, round(avg(duration)/1e6,3) avg_ms FROM abnormal_traces WHERE service_name='frontend' AND span_name='user.User/CheckUser' GROUP BY 1,2", "claim": "All 200 frontend CheckUser calls to user fail in about 0.02 ms; the normal period had 529 calls with no errors."},
        {"kind": "trace", "sql": "SELECT service_name, span_name, attr_span_kind, count(*) n FROM normal_traces WHERE service_name='user' GROUP BY 1,2,3", "claim": "The user service emitted 503 server spans in the normal period and none in the abnormal period."}
      ]
    }
  ],
  "propagation": [
    {"from": "user", "to": "frontend",
     "evidence": [
       {"kind": "trace", "sql": "SELECT span_name, attr_http_response_status_code, attr_status_code, count(*) n FROM abnormal_traces WHERE service_name='frontend' AND attr_span_kind='Server' AND attr_status_code='Error' GROUP BY 1,2,3", "claim": "Frontend HTTP server spans for /cinema, /museums, /restaurants, /user and /reservation return 500 within about 0.1 ms, tracking the failed user auth calls."},
       {"kind": "log", "sql": "SELECT service_name, level, message, count(*) n FROM abnormal_logs WHERE service_name='frontend' AND level='ERROR' GROUP BY 1,2,3", "claim": "Frontend logs 34 ERROR entries reading 'User authentication failed' during the abnormal window."}
     ]}
  ]
}
